const MESES = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
  "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
const ANOS = [2026, 2027]; // conforme o plano: apenas 2026 e 2027
const DIA_SEMANA = ["Domingo", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado"];
const TAREFAS = ["Fazer o café", "Lavar a garrafa", "Organizar a mesa"];

const pad2 = (n) => String(n).padStart(2, "0");
const escXml = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

// Preenche automaticamente os dias do mês; exclui domingo e (opcionalmente) sábado.
function construirDias(mes, ano, incluirSabado) {
  const total = new Date(ano, mes + 1, 0).getDate();
  const dias = [];
  for (let d = 1; d <= total; d++) {
    const wd = new Date(ano, mes, d).getDay(); // 0 = domingo ... 6 = sábado
    if (wd === 0) continue;
    if (wd === 6 && !incluirSabado) continue;
    dias.push({ dia: DIA_SEMANA[wd], data: `${pad2(d)}/${pad2(mes + 1)}/${ano}` });
  }
  return dias;
}

// Distribuição automatizada e equilibrada (rodízio circular).
function distribuir(dias, participantes, porDia) {
  const n = participantes.length;
  let ptr = 0;
  return dias.map((cell) => {
    const nomes = [];
    for (let k = 0; k < porDia; k++) nomes.push(participantes[ptr++ % n]);
    return { ...cell, nomes };
  });
}

// Quantas vezes cada participante aparece (para o resumo de equilíbrio).
function contarOcorrencias(linhas, participantes) {
  const c = Object.fromEntries(participantes.map((p) => [p, 0]));
  linhas.forEach((l) => l.nomes.forEach((nm) => { c[nm] = (c[nm] || 0) + 1; }));
  const vals = Object.values(c);
  return { min: vals.length ? Math.min(...vals) : 0, max: vals.length ? Math.max(...vals) : 0 };
}

// Gera o mural padronizado como SVG (base do PNG/PDF e da pré-visualização).
function construirMuralSVG({ mes, ano, setor, porDia, sabado, linhas }) {
  const W = 900, H = 1273;
  const red = "#E82224", red700 = "#C4171B", ink = "#201B1C";
  const cream = "#FBF6EE", line = "#E7E3E2", yellow = "#F5C518";
  const disp = "'Archivo','Arial Black',Arial,sans-serif";
  const body = "Arial,Helvetica,sans-serif";
  const cx0 = 100, cx1 = 860, barW = 64;
  const tableTop = 176, headerH = 34, bandTop = 1055;
  const bodyTop = tableTop + headerH;
  const rows = Math.max(linhas.length, 1);
  const rowH = Math.min(38, Math.max(20, (bandTop - bodyTop - 8) / rows));
  const fs = Math.max(11, Math.min(15, rowH * 0.42));
  const colDia = 118, colData = 340, colResp = 566;
  const respLabel = porDia === 2 ? "DUPLA RESPONSÁVEL" : "RESPONSÁVEL";
  const badge = `${MESES[mes]} / ${ano}`;

  const sidebar =
    `<rect x="0" y="0" width="${barW}" height="${H}" fill="${red}"/>` +
    `<text x="${barW / 2}" y="${H * 0.6}" transform="rotate(-90 ${barW / 2} ${H * 0.6})" text-anchor="middle" font-family="${disp}" font-weight="800" font-size="24" letter-spacing="6" fill="${yellow}">CRONOGRAMA CAFÉ</text>`;

  const header =
    `<text x="${cx0}" y="98" font-family="${disp}" font-weight="800" font-size="40" letter-spacing="-1" fill="${ink}">CRONOGRAMA DO CAFÉ${setor ? ` <tspan fill="${red}">— ${escXml(setor)}</tspan>` : ""}</text>` +
    `<text x="${cx0}" y="128" font-family="${disp}" font-weight="700" font-size="13" letter-spacing="3" fill="#8a8284">ESCALA DE RESPONSÁVEIS · DIAS ÚTEIS${sabado ? " + SÁBADO" : ""}</text>`;

  const badgeW = 196, badgeH = 44, bX = cx1 - badgeW, bY = 64;
  const badgeSvg =
    `<rect x="${bX}" y="${bY}" width="${badgeW}" height="${badgeH}" rx="${badgeH / 2}" fill="${yellow}"/>` +
    `<text x="${bX + badgeW / 2}" y="${bY + badgeH / 2 + 6}" text-anchor="middle" font-family="${disp}" font-weight="800" font-size="18" fill="${red700}">${escXml(badge)}</text>`;

  const rule = `<rect x="${cx0}" y="150" width="${cx1 - cx0}" height="4" rx="2" fill="${red}"/>`;

  const thead =
    `<rect x="${cx0}" y="${tableTop}" width="${cx1 - cx0}" height="${headerH}" rx="4" fill="${ink}"/>` +
    `<text x="${colDia}" y="${tableTop + headerH / 2 + 5}" font-family="${disp}" font-weight="700" font-size="13" letter-spacing="1.5" fill="#fff">DIA</text>` +
    `<text x="${colData}" y="${tableTop + headerH / 2 + 5}" font-family="${disp}" font-weight="700" font-size="13" letter-spacing="1.5" fill="#fff">DATA</text>` +
    `<text x="${colResp}" y="${tableTop + headerH / 2 + 5}" font-family="${disp}" font-weight="700" font-size="13" letter-spacing="1.5" fill="#fff">${respLabel}</text>`;

  let corpo = "";
  if (linhas.length === 0) {
    corpo = `<text x="${(cx0 + cx1) / 2}" y="${bodyTop + 120}" text-anchor="middle" font-family="${body}" font-size="16" fill="#a49c9d">Adicione participantes para gerar a escala.</text>`;
  } else {
    linhas.forEach((r, i) => {
      const y = bodyTop + i * rowH;
      const alt = i % 2 === 1;
      const ty = y + rowH / 2 + fs * 0.35;
      if (alt) corpo += `<rect x="${cx0}" y="${y}" width="${cx1 - cx0}" height="${rowH}" fill="${cream}"/>`;
      corpo += `<line x1="${cx0}" y1="${y}" x2="${cx1}" y2="${y}" stroke="${line}" stroke-width="1"/>`;
      if (alt) corpo += `<rect x="${colData - 18}" y="${y + rowH / 2 - 4}" width="8" height="8" rx="1.5" fill="${yellow}"/>`;
      corpo += `<text x="${colDia}" y="${ty}" font-family="${disp}" font-weight="700" font-size="${fs}" fill="${ink}">${escXml(r.dia)}</text>`;
      corpo += `<text x="${colData}" y="${ty}" font-family="${body}" font-size="${fs}" fill="#4a4344">${escXml(r.data)}</text>`;
      if (r.nomes.length === 2) {
        corpo += `<text x="${colResp}" y="${ty}" font-family="${body}" font-size="${fs}" fill="${ink}">` +
          `<tspan font-weight="600">${escXml(r.nomes[0])}</tspan>` +
          `<tspan fill="${red}" font-weight="700"> + </tspan>` +
          `<tspan font-weight="600">${escXml(r.nomes[1])}</tspan></text>`;
      } else {
        corpo += `<text x="${colResp}" y="${ty}" font-family="${body}" font-weight="600" font-size="${fs}" fill="${ink}">${escXml(r.nomes[0] || "")}</text>`;
      }
    });
    corpo += `<line x1="${cx0}" y1="${bodyTop + linhas.length * rowH}" x2="${cx1}" y2="${bodyTop + linhas.length * rowH}" stroke="${line}" stroke-width="1"/>`;
  }

  const mx = 118, my = 1088;
  const mascote =
    `<circle cx="${mx + 70}" cy="${my + 66}" r="66" fill="${red}"/>` +
    `<rect x="${mx + 44}" y="${my + 52}" width="52" height="44" rx="8" fill="#fff"/>` +
    `<rect x="${mx + 44}" y="${my + 52}" width="52" height="12" rx="6" fill="${yellow}"/>` +
    `<path d="M${mx + 96} ${my + 60} h14 a11 11 0 0 1 0 22 h-14" fill="none" stroke="#fff" stroke-width="7"/>` +
    `<path d="M${mx + 60} ${my + 40} q7 -11 0 -22" stroke="#fff" stroke-width="4" fill="none" stroke-linecap="round"/>` +
    `<path d="M${mx + 78} ${my + 40} q7 -11 0 -22" stroke="#fff" stroke-width="4" fill="none" stroke-linecap="round"/>` +
    `<text x="${mx + 70}" y="${my + 168}" text-anchor="middle" font-family="${disp}" font-weight="700" font-size="11" letter-spacing="1" fill="#b7b0b1">MASCOTE ${escXml(setor || "GPE")}</text>`;

  const tbX = 470, tbY = 1085, tbW = 390, tbH = 152;
  const tarefas =
    `<rect x="${tbX}" y="${tbY}" width="${tbW}" height="${tbH}" rx="14" fill="#FFFDF6" stroke="${yellow}" stroke-width="2"/>` +
    `<text x="${tbX + 22}" y="${tbY + 34}" font-family="${disp}" font-weight="700" font-size="15" letter-spacing="1" fill="${red700}"><tspan fill="${yellow}">★ </tspan>TAREFAS DO DIA</text>` +
    TAREFAS.map((t, i) =>
      `<circle cx="${tbX + 26}" cy="${tbY + 66 + i * 28}" r="4" fill="${red}"/>` +
      `<text x="${tbX + 40}" y="${tbY + 71 + i * 28}" font-family="${body}" font-size="14" fill="${ink}">${escXml(t)}</text>`
    ).join("");

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">` +
    `<rect x="0" y="0" width="${W}" height="${H}" fill="#ffffff"/>` +
    sidebar + header + badgeSvg + rule + thead + corpo + mascote + tarefas + `</svg>`;
}

// Exporta o mural em PNG (offline, sem dependências externas).
function exportarPNG(svg, nome) {
  const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml;charset=utf-8" }));
  const img = new Image();
  img.onload = () => {
    const scale = 2, canvas = document.createElement("canvas");
    canvas.width = 900 * scale; canvas.height = 1273 * scale;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    URL.revokeObjectURL(url);
    canvas.toBlob((b) => {
      const a = document.createElement("a");
      a.href = URL.createObjectURL(b); a.download = nome; a.click();
      setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    }, "image/png");
  };
  img.onerror = () => { URL.revokeObjectURL(url); alert("Não foi possível gerar o PNG neste navegador. Use “Imprimir / PDF”."); };
  img.src = url;
}

// Abre o mural em uma janela de impressão (permite salvar em PDF, offline).
function imprimirSVG(svg) {
  const w = window.open("", "_blank");
  if (!w) { alert("Permita pop-ups para imprimir ou salvar em PDF."); return; }
  w.document.write(
    `<!doctype html><html><head><meta charset="utf-8"><title>Cronograma do Café</title>` +
    `<style>@page{size:A4 portrait;margin:0}html,body{margin:0;padding:0}svg{width:100%;height:auto;display:block}</style>` +
    `</head><body>${svg}<scr` + `ipt>window.onload=function(){setTimeout(function(){window.print()},250)}</scr` + `ipt></body></html>`
  );
  w.document.close();
}

