// Escapa texto para uso seguro dentro do HTML da assinatura.
const escSig = (s) => (s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// Máscara de telefone: (XX) XXXXX-XXXX (celular) ou (XX) XXXX-XXXX (fixo).
function maskPhone(v) {
  const d = (v || "").replace(/\D/g, "").slice(0, 11); // só dígitos, máx. 11
  if (d.length === 0) return "";
  if (d.length <= 2) return "(" + d;
  const ddd = d.slice(0, 2);
  const rest = d.slice(2);
  if (rest.length <= 4) return `(${ddd}) ${rest}`;
  if (rest.length <= 8) return `(${ddd}) ${rest.slice(0, 4)}-${rest.slice(4)}`;
  return `(${ddd}) ${rest.slice(0, 5)}-${rest.slice(5)}`;
}

// Monta o HTML da assinatura (tabelas + estilos inline) — padrão Grupo MM.
function buildSignature(d) {
  const FF = "'Century Gothic','Trebuchet MS',Arial,sans-serif";
  const RED = "#E1120F";
  const W = 600;

  // foto redonda opcional (à esquerda)
  let photoCell = "";
  if (d.photo) {
    photoCell = `<td width="84" style="vertical-align:middle;padding:24px 14px 24px 2px;">`
      + `<!-- Foto do colaborador (base64). Para Outlook, hospede em URL pública e troque o src. -->`
      + `<img src="${d.photo}" alt="${escSig(d.nome)}" width="66" height="66" `
      + `style="display:block;border-radius:50%;object-fit:cover;border:0;"></td>`;
  }

  // linha do telefone opcional (bolinha vermelha + número)
  let phoneLine = "";
  if (d.fone) {
    phoneLine = `<p style="margin:7px 0 0 0;font-family:${FF};font-size:13px;color:#3d3d3d;line-height:1.2;">`
      + `<span style="color:${RED};font-size:13px;line-height:1;vertical-align:middle;">&#9679;</span>&nbsp;`
      + `<span style="vertical-align:middle;">${escSig(d.fone)}</span></p>`;
  }

  return `<table width="${W}" border="0" cellspacing="0" cellpadding="0" style="border-collapse:collapse;font-family:${FF};max-width:${W}px;">
  <tr>
    <td width="4" bgcolor="${RED}" style="background-color:${RED};width:4px;font-size:0;line-height:0;">&nbsp;</td>
    <td width="16" style="font-size:0;line-height:0;">&nbsp;</td>
    ${photoCell}<td style="vertical-align:middle;padding-right:14px;">
      <p style="margin:0;font-family:${FF};font-size:16px;font-weight:bold;color:#1a1a1a;line-height:1.15;letter-spacing:-0.01em;">${escSig(d.nome)}</p>
      <p style="margin:3px 0 0 0;font-family:${FF};font-size:14px;font-weight:bold;color:${RED};line-height:1.2;">${escSig(d.depto)}</p>
      ${phoneLine}
    </td>
    <td align="right" style="vertical-align:middle;text-align:right;">
      <table border="0" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">
        <tr>
          <td style="vertical-align:bottom;padding-right:8px;padding-bottom:2px;">
            <!-- Logo Grupo MM (base64). Para Outlook, hospede em URL pública e troque o src. -->
            <img src="${LOGO_MM}" alt="${escSig(EMPRESA_MM)}" width="120" style="display:block;border:0;height:auto;"></td>
          <td style="vertical-align:bottom;padding-top:18px;">
            <!-- Mascote Xicória (base64). Para Outlook, hospede em URL pública e troque o src. -->
            <img src="${MASCOTE}" alt="Mascote Grupo MM" width="66" style="display:block;border:0;height:auto;"></td>
        </tr>
      </table>
    </td>
  </tr>
</table>`;
}

function AssinaturaScreen() {
  const [nome, setNome] = useState("");
  const [depto, setDepto] = useState("");
  const [fone, setFone] = useState("");
  const [photo, setPhoto] = useState(null);
  const [erro, setErro] = useState("");
  const [copiado, setCopiado] = useState(""); // "" | "sig" | "code"
  const fileRef = React.useRef(null);

  const dados = { nome: nome.trim(), depto: depto.trim(), fone: fone.trim(), photo };
  const valido = !!(dados.nome && dados.depto);
  const html = React.useMemo(() => buildSignature(dados), [nome, depto, fone, photo]);

  function carregarFoto(file) {
    if (!file || !file.type || !file.type.startsWith("image/")) return;
    const r = new FileReader();
    r.onload = (ev) => setPhoto(ev.target.result);
    r.readAsDataURL(file);
  }

  function removerFoto() {
    setPhoto(null);
    if (fileRef.current) fileRef.current.value = "";
  }

  function limpar() {
    setNome(""); setDepto(""); setFone(""); setErro(""); setCopiado("");
    removerFoto();
  }

  function flash(which) {
    setCopiado(which);
    setTimeout(() => setCopiado(""), 1600);
  }

  function exigirValido() {
    if (valido) return true;
    setErro("Preencha nome completo e departamento/filial para gerar a assinatura.");
    return false;
  }

  async function copiarCodigo() {
    if (!exigirValido()) return;
    try { await navigator.clipboard.writeText(html); } catch (e) { /* ignora */ }
    flash("code");
  }

  async function copiarAssinatura() {
    if (!exigirValido()) return;
    try {
      await navigator.clipboard.write([new ClipboardItem({
        "text/html": new Blob([html], { type: "text/html" }),
        "text/plain": new Blob([html], { type: "text/plain" }),
      })]);
    } catch (e) {
      try { await navigator.clipboard.writeText(html); } catch (_) { /* ignora */ }
    }
    flash("sig");
  }

  return (
    <div className="screen">
      <PageHead icon={PenLine} fase={1} titulo="Gerador de Assinatura de E-mail"
        sub="Régua vermelha, foto redonda, nome em destaque e o logo com o mascote à direita — padrão Grupo MM. Telefone e foto são opcionais." />
      <div className="sig-work">
        <div className="form-card">
          <h3 className="form-title">Dados da assinatura</h3>
          <div className="grid-2">
            <Field label="Nome completo">
              <input className={`input ${erro && !dados.nome ? "err" : ""}`} value={nome}
                placeholder="Ex.: Ana Souza" autoComplete="name"
                onChange={(e) => { setNome(e.target.value); setErro(""); }} />
            </Field>
            <Field label="Departamento ou Filial">
              <input className={`input ${erro && !dados.depto ? "err" : ""}`} value={depto}
                placeholder="Ex.: Recursos Humanos"
                onChange={(e) => { setDepto(e.target.value); setErro(""); }} />
            </Field>
            <Field label="Telefone" hint="Opcional">
              <input className="input" value={fone} inputMode="numeric" maxLength={15}
                placeholder="(00) 00000-0000"
                onChange={(e) => setFone(maskPhone(e.target.value))} />
            </Field>
            <Field label="Foto" hint="Opcional — retrato redondo à esquerda">
              <div className="sig-photo-row">
                <div className={`dropzone up ${photo ? "has" : ""}`}
                  onClick={() => fileRef.current && fileRef.current.click()}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => { e.preventDefault(); carregarFoto(e.dataTransfer.files[0]); }}>
                  {photo ? (
                    <><img className="sig-photo-thumb" src={photo} alt="Prévia da foto" /><span>Trocar foto</span></>
                  ) : (
                    <><Upload size={18} /><span>Enviar foto</span><small>PNG ou JPG · quadrada fica melhor</small></>
                  )}
                </div>
                {photo && <button type="button" className="sig-rm" onClick={removerFoto}>remover</button>}
              </div>
              <input ref={fileRef} type="file" accept="image/*" hidden
                onChange={(e) => carregarFoto(e.target.files[0])} />
            </Field>
          </div>

          {erro && <div className="sig-err">{erro}</div>}

          <div className="gen-row">
            <button className="btn btn-primary" disabled={!valido} onClick={copiarAssinatura}>
              <Copy size={16} /> Copiar assinatura
            </button>
            <button className="btn btn-ghost" onClick={limpar}>Limpar campos</button>
            {copiado === "sig" && <span className="sig-toast">assinatura copiada</span>}
          </div>
        </div>

        <div className="sig-result">
          <PreviewShell>
            {valido ? (
              <div className="sig-render" dangerouslySetInnerHTML={{ __html: html }} />
            ) : (
              <div className="sig-empty">Preencha <strong>nome completo</strong> e <strong>departamento/filial</strong> para ver a prévia.</div>
            )}
            <span className="preview-note">Prévia da assinatura — atualiza em tempo real.</span>
          </PreviewShell>

          <div className="outputs">
            <div className="sig-out-head">
              <h4>Código HTML</h4>
              {copiado === "code" && <span className="sig-toast">código copiado</span>}
              <button className="btn btn-ghost sm" disabled={!valido} onClick={copiarCodigo}>
                <Copy size={14} /> Copiar código
              </button>
            </div>
            <textarea className="sig-code" readOnly spellCheck={false}
              value={valido ? html : ""}
              placeholder="O código HTML aparece aqui depois de preencher os campos obrigatórios." />
          </div>
        </div>
      </div>
    </div>
  );
}

function CafeScreen() {
  const [mes, setMes] = useState(6);   // Julho (para refletir o mural de referência)
  const [ano, setAno] = useState(2026);
  const [setor, setSetor] = useState("GPE");
  const [porDia, setPorDia] = useState(2);
  const [sabado, setSabado] = useState(false);
  const [texto, setTexto] = useState(
    "Larissa\nEderson\nClaudia\nEliabe\nCamila\nDani B\nDani P\nTiago\nEduardo\nMaria\nDahiane\nRodrigo\nGabriela\nGabrielly"
  );

  const participantes = texto.split("\n").map((s) => s.trim()).filter(Boolean);
  const dias = construirDias(mes, ano, sabado);
  const podeGerar = participantes.length >= porDia;
  const linhas = podeGerar ? distribuir(dias, participantes, porDia) : [];
  const svg = construirMuralSVG({ mes, ano, setor: setor.trim(), porDia, sabado, linhas });
  const eq = contarOcorrencias(linhas, participantes);
  const nomeArq = `cronograma-cafe-${MESES[mes].toLowerCase()}-${ano}`;

  return (
    <div className="screen">
      <PageHead icon={Coffee} fase={2} titulo="Gerador do Cronograma do Café"
        sub="Distribui os turnos de forma equilibrada e monta o mural no padrão do Grupo MM." />
      <div className="work">
        <div className="form-card">
          <h3 className="form-title">Configuração da escala</h3>

          <div className="grid-2">
            <Field label="Mês">
              <select className="input" value={mes} onChange={(e) => setMes(Number(e.target.value))}>
                {MESES.map((m, i) => <option key={m} value={i}>{m}</option>)}
              </select>
            </Field>
            <Field label="Ano">
              <select className="input" value={ano} onChange={(e) => setAno(Number(e.target.value))}>
                {ANOS.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </Field>
          </div>

          <Field label="Setor / equipe" hint="Aparece no título do mural (ex.: GPE)">
            <input className="input" value={setor} onChange={(e) => setSetor(e.target.value)} placeholder="Ex.: GPE" />
          </Field>

          <Field label="Participantes" hint="Um nome por linha — a ordem define o rodízio">
            <textarea className="input" rows={7} value={texto} onChange={(e) => setTexto(e.target.value)}
              placeholder={"Larissa\nEderson\nClaudia\n…"} />
          </Field>

          <div className="grid-2">
            <Field label="Responsáveis por dia">
              <div className="segmented">
                <button type="button" className={porDia === 1 ? "active" : ""} onClick={() => setPorDia(1)}>1 pessoa</button>
                <button type="button" className={porDia === 2 ? "active" : ""} onClick={() => setPorDia(2)}>Dupla</button>
              </div>
            </Field>
            <Field label="Sábado">
              <label className="switch-row">
                <input type="checkbox" checked={sabado} onChange={(e) => setSabado(e.target.checked)} />
                <span>Incluir sábado na escala</span>
              </label>
            </Field>
          </div>

          <div className="calc-note">
            <CalendarDays size={15} />
            {podeGerar ? (
              <span>{dias.length} dias em {MESES[mes]}/{ano} · cada pessoa entra {eq.min === eq.max ? `${eq.min}` : `${eq.min}–${eq.max}`} vez(es).</span>
            ) : (
              <span>Adicione ao menos {porDia} participante(s) para gerar a dupla.</span>
            )}
          </div>

          <div className="gen-row">
            <button className="btn btn-primary" disabled={!podeGerar} onClick={() => exportarPNG(svg, `${nomeArq}.png`)}>
              <Download size={16} /> Baixar imagem (PNG)
            </button>
            <button className="btn btn-ghost" disabled={!podeGerar} onClick={() => imprimirSVG(svg)}>
              <Printer size={16} /> Imprimir / PDF
            </button>
          </div>
        </div>

        <div className="side">
          <PreviewShell aspect="portrait">
            <div className="mural-wrap" dangerouslySetInnerHTML={{ __html: svg }} />
            <span className="preview-note">Mural padronizado — atualiza em tempo real conforme os campos.</span>
          </PreviewShell>
          <div className="outputs">
            <h4>Saídas</h4>
            <p className="out-line"><Download size={14} /> Imagem PNG em alta resolução (compartilhar)</p>
            <p className="out-line"><Printer size={14} /> Impressão A4 / salvar em PDF (mural)</p>
          </div>
        </div>
      </div>
    </div>
  );
}

