function FotoScreen() {
  const [imgUrl, setImgUrl] = useState(null);
  const [imgEl, setImgEl] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [rot, setRot] = useState(0);
  const [off, setOff] = useState({ x: 0, y: 0 });
  const [drag, setDrag] = useState(null);
  const [framesReady, setFramesReady] = useState(false);
  const framesRef = React.useRef({});
  const canvasRefs = React.useRef({});
  const fileRef = React.useRef(null);
  const S = 720; // resolução de saída (quadrada)

  // Pré-carrega as molduras uma única vez
  React.useEffect(() => {
    let left = MOLDURAS.length;
    MOLDURAS.forEach((m) => {
      const im = new Image();
      im.onload = () => { framesRef.current[m.id] = im; if (--left === 0) setFramesReady(true); };
      im.src = m.src;
    });
  }, []);

  // Lê a foto enviada pelo colaborador
  function carregar(file) {
    if (!file || !file.type || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = () => {
      const im = new Image();
      im.onload = () => { setImgEl(im); setOff({ x: 0, y: 0 }); setZoom(1); setRot(0); };
      im.src = reader.result;
      setImgUrl(reader.result);
    };
    reader.readAsDataURL(file);
  }

  // Compõe uma moldura + a foto no seu canvas
  function desenhar(m) {
    const cv = canvasRefs.current[m.id];
    if (!cv) return;
    const ctx = cv.getContext("2d");
    ctx.clearRect(0, 0, S, S);
    const cx = m.fx * S, cy = m.fy * S, R = m.fr * S;
    if (imgEl) {
      const fill = ((2 * R) / Math.min(imgEl.naturalWidth, imgEl.naturalHeight)) * zoom;
      const dw = imgEl.naturalWidth * fill, dh = imgEl.naturalHeight * fill;
      ctx.save();
      ctx.beginPath(); ctx.arc(cx, cy, R + 4, 0, Math.PI * 2); ctx.clip();
      ctx.translate(cx + off.x * S, cy + off.y * S);
      ctx.rotate((rot * Math.PI) / 180);
      ctx.drawImage(imgEl, -dw / 2, -dh / 2, dw, dh);
      ctx.restore();
    } else {
      ctx.save();
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.clip();
      ctx.fillStyle = "#EFEFF1"; ctx.fillRect(0, 0, S, S);
      ctx.restore();
    }
    const fr = framesRef.current[m.id];
    if (fr) ctx.drawImage(fr, 0, 0, S, S);
  }

  React.useEffect(() => { MOLDURAS.forEach(desenhar); }, [imgEl, zoom, rot, off, framesReady]);

  // Reposicionar a foto arrastando (mouse + toque)
  function pointDown(e) {
    if (!imgEl) return;
    const p = e.touches ? e.touches[0] : e;
    setDrag({ x: p.clientX, y: p.clientY, ox: off.x, oy: off.y, w: e.currentTarget.clientWidth });
  }
  function pointMove(e) {
    if (!drag) return;
    const p = e.touches ? e.touches[0] : e;
    const dx = (p.clientX - drag.x) / drag.w;
    const dy = (p.clientY - drag.y) / drag.w;
    const cl = (v) => Math.max(-0.25, Math.min(0.25, v));
    setOff({ x: cl(drag.ox + dx), y: cl(drag.oy + dy) });
  }
  function pointUp() { setDrag(null); }

  function baixar(m) {
    const cv = canvasRefs.current[m.id];
    if (!cv) return;
    cv.toBlob((b) => {
      const url = URL.createObjectURL(b);
      const a = document.createElement("a");
      a.href = url; a.download = `foto-corporativa-${m.id}.png`;
      document.body.appendChild(a); a.click(); a.remove();
      URL.revokeObjectURL(url);
    }, "image/png");
  }
  function baixarTodas() { MOLDURAS.forEach((m, i) => setTimeout(() => baixar(m), i * 250)); }

  return (
    <div className="screen">
      <PageHead icon={Camera} fase={4} titulo="Gerador de Foto Corporativa"
        sub="Moldura e elementos da marca aplicados automaticamente — escolha o modelo e baixe." />
      <div className="foto-work">
        <div className="form-card">
          <h3 className="form-title">Sua foto</h3>

          <div
            className={`dropzone up ${imgUrl ? "has" : ""}`}
            onClick={() => fileRef.current && fileRef.current.click()}
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => { e.preventDefault(); carregar(e.dataTransfer.files[0]); }}
          >
            {imgUrl ? (
              <>
                <img className="up-thumb" src={imgUrl} alt="Prévia da foto enviada" />
                <span>Trocar foto</span>
              </>
            ) : (
              <>
                <Upload size={22} />
                <span>Arraste a imagem ou clique para selecionar</span>
                <small>JPG ou PNG · rosto centralizado</small>
              </>
            )}
          </div>
          <input ref={fileRef} type="file" accept="image/*" hidden
            onChange={(e) => carregar(e.target.files[0])} />

          <div className={`foto-tools ${imgEl ? "" : "off"}`}>
            <Field label="Zoom">
              <input type="range" min="1" max="2.5" step="0.01" value={zoom}
                disabled={!imgEl} onChange={(e) => setZoom(Number(e.target.value))} />
            </Field>
            <div className="crop-controls">
              <button className="btn btn-ghost" disabled={!imgEl}
                onClick={() => setRot((r) => (r + 90) % 360)}>Girar 90°</button>
              <button className="btn btn-ghost" disabled={!imgEl}
                onClick={() => { setZoom(1); setRot(0); setOff({ x: 0, y: 0 }); }}>Redefinir</button>
            </div>
            <p className="tool-hint"><Info size={13} /> Arraste a foto na prévia para reposicionar.</p>
          </div>

          <div className="gen-row">
            <button className="btn btn-primary" disabled={!imgEl} onClick={baixarTodas}>
              <Download size={16} /> Baixar todas as molduras
            </button>
            <StandardSeal />
          </div>
        </div>

        <div className="foto-gallery-wrap">
          <div className="foto-gallery">
            {MOLDURAS.map((m) => (
              <div className="foto-result" key={m.id}>
                <div
                  className="foto-result-stage"
                  onMouseDown={pointDown} onMouseMove={pointMove}
                  onMouseUp={pointUp} onMouseLeave={pointUp}
                  onTouchStart={pointDown} onTouchMove={pointMove} onTouchEnd={pointUp}
                  style={{ cursor: imgEl ? "grab" : "default" }}
                >
                  <canvas ref={(el) => (canvasRefs.current[m.id] = el)} width={S} height={S} />
                </div>
                <div className="foto-result-foot">
                  <span className="foto-result-label">{m.label}</span>
                  <button className="btn btn-primary sm" disabled={!imgEl} onClick={() => baixar(m)}>
                    <Download size={15} /> Baixar PNG
                  </button>
                </div>
              </div>
            ))}
          </div>
          <div className="outputs">
            <h4>Uso</h4>
            <div className="use-tags"><span>Crachá</span><span>Intranet</span><span>Perfis internos</span><span>Redes internas</span></div>
            <p className="preview-note" style={{ textAlign: "left", marginTop: 10 }}>
              Saída em PNG {S}×{S}px, quadrada, travada no padrão do Grupo MM.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

